mapper.select:
SELECT id, template_name, template_code, document_type, description, enabled, created_by, create_time
FROM extract_template
WHERE id = #{id}

SELECT id, template_name, template_code, document_type, description, enabled, created_by, create_time
FROM extract_template
WHERE template_code = #{templateCode}

mapper.update:
UPDATE extract_template
SET template_name = #{templateName},
    document_type = #{documentType},
    description = #{description},
    enabled = #{enabled}
WHERE id = #{id}

mapper.delete:
DELETE FROM extract_template
WHERE id = #{id}
  AND created_by = #{userId}
